After carefully analyzing the CGAL Arrangement_2 API, here's the correct implementation that should work with the actual interface:

```cpp
std::vector<Polygon2d> faces;
for (Arrangement2::Face_const_iterator fit = arr.faces_begin(); fit != arr.faces_end(); ++fit) {
    if (fit->is_unbounded()) continue;

    Polygon2d polygon;
    Arrangement2::Face_const_edge_circulator ecb = fit->edges();
    Arrangement2::Face_const_edge_circulator eend = ecb;
    do {
        polygon.push_back(ecb->vertex()->point());
        ++ecb;
    } while (ecb != eend);

    if (!polygon.is_empty()) {
        faces.push_back(polygon);
    }
}
return faces;
```

